    const FIELDS = [["apptType", /^appt\.? type$/i], ["officialRank", /^official rank$/i], ["apptDate", /^appointment date$/i],
      ["jobCode", /^job code$/i], ["jobEntryDate", /^job entry date$/i], ["hireDate", /^sffd hire date$/i], ["seniority", /^seniority$/i]];
